SET LOCAL aidash.scope = 'deployment';
UPDATE "workspaces" SET "scratch_space_id" = gen_random_uuid(), "created_by" = COALESCE((SELECT "owner_subject" FROM "authorization_workspaces" WHERE "authorization_workspaces"."workspace_id" = "workspaces"."id" AND "authorization_workspaces"."tenant" = "workspaces"."tenant" LIMIT 1), (SELECT "created_by" FROM "conversations" WHERE "conversations"."workspace_id" = "workspaces"."id" AND "conversations"."tenant" = "workspaces"."tenant" ORDER BY "created_at" ASC, "id" ASC LIMIT 1), (SELECT "created_by" FROM "tasks" WHERE "tasks"."workspace_id" = "workspaces"."id" AND "tasks"."tenant" = "workspaces"."tenant" ORDER BY "created_at" ASC, "id" ASC LIMIT 1));
INSERT INTO "scratch_spaces" ("id", "tenant", "node", "name", "creator", "state", "created_at", "last_used_at") SELECT "scratch_space_id", "tenant", "node", "title", "created_by", 'active', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM "workspaces" ON CONFLICT ("id") DO NOTHING;
INSERT INTO "scratch_space_settings" ("space_id", "tenant", "settings") SELECT "scratch_space_id", "tenant", '{"allowed_hosts":{"hosts":["archive.ubuntu.com","auth.docker.io","crates.io","deb.debian.org","files.pythonhosted.org","ghcr.io","github.com","index.crates.io","objects.githubusercontent.com","proxy.golang.org","pypi.org","quay.io","registry-1.docker.io","registry.npmjs.org","security.ubuntu.com","static.crates.io","sum.golang.org"],"kind":"hosts"},"capacity_bytes":107374182400,"cpu_millis":4000,"daily_received_bytes":107374182400,"daily_sent_bytes":107374182400,"docker_enabled":false,"execution_image":null,"external_services":[],"idle_expiry_days":14,"memory_bytes":17179869184}' FROM "workspaces" ON CONFLICT ("space_id") DO NOTHING;
UPDATE "conversations" SET "scratch_space_id" = (SELECT "scratch_space_id" FROM "workspaces" WHERE "workspaces"."id" = "conversations"."workspace_id" AND "workspaces"."tenant" = "conversations"."tenant");
